//! Every Bloblang method and function example of Bento 1.22.0's docs, mapped by ekiben and
//! compared byte for byte with what `.bento/bento blobl` printed for it
//! (tests/parity/examples.json, regenerated by scripts/parity-examples.py).

use ekiben_bloblang::cli::run_line;
use ekiben_bloblang::env::MemoryImporter;
use ekiben_bloblang::Environment;
use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;

/// Cases no byte comparison can hold: (method, text the mapping contains, reason).
const SKIPPED: &[(&str, &str, &str)] = &[
    ("compress", "compress(\"gzip\")", "deflate bytes are implementation-defined: Go's compress/flate writes 161 bytes where flate2 writes a valid 160; decompress round-trips both"),
    ("sign_jwt_es256", "", "docs key is a placeholder (`... signature data ...`); Bento marks the example SkipTesting and fails to parse it"),
    ("sign_jwt_es384", "", "docs key is a placeholder; Bento marks the example SkipTesting"),
    ("sign_jwt_es512", "", "docs key is a placeholder; Bento marks the example SkipTesting"),
    ("sign_jwt_rs256", "", "docs key is a placeholder; Bento marks the example SkipTesting"),
    ("sign_jwt_rs384", "", "docs key is a placeholder; Bento marks the example SkipTesting"),
    ("sign_jwt_rs512", "", "docs key is a placeholder; Bento marks the example SkipTesting"),
];

/// stdout and stderr of `printf '%s\n' input | bento blobl mapping` for one case.
fn ekiben_output(env: &Environment, mapping: &str, input: &str) -> (String, String) {
    let exec = match env.compile_mapping(mapping) {
        Ok(e) => e,
        Err(e) => return (String::new(), format!("failed to parse mapping: {e}\n")),
    };
    match run_line(&exec, input.as_bytes(), false) {
        Ok(out) => (format!("{out}\n"), String::new()),
        Err(err) => (String::new(), format!("{err}\n")),
    }
}

#[test]
fn bento_docs_examples_match_bento_output() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/parity");
    let text = std::fs::read_to_string(dir.join("examples.json")).expect("examples.json");
    let cases: Vec<serde_json::Value> = serde_json::from_str(&text).expect("examples.json parses");
    let vars: HashMap<String, String> = [
        ("BENTO_TEST_BLOBLANG_FILE", "file.json"),
        ("BENTO_TEST_BLOBLANG_SCHEMA_FILE", "schema.json"),
    ]
    .into_iter()
    .map(|(k, f)| (k.to_string(), dir.join(f).display().to_string()))
    .collect();
    let files = vars
        .values()
        .map(|p| (p.clone(), std::fs::read(p).expect("parity fixture")))
        .collect();
    let env = Environment::new()
        .with_env_vars(vars)
        .with_host_file(true)
        .with_importer(Arc::new(MemoryImporter { files }));

    let mut failed = Vec::new();
    let mut compared = 0;
    for case in &cases {
        let field = |k: &str| case[k].as_str().unwrap_or_default().to_string();
        let name = field("name");
        let mapping = field("mapping");
        if SKIPPED
            .iter()
            .any(|(n, text, _)| *n == name && mapping.contains(text))
        {
            continue;
        }
        compared += 1;
        let (out, err) = ekiben_output(&env, &field("mapping"), &field("input"));
        let want_out = case["bento"]["stdout"].as_str().unwrap_or_default();
        let want_err = case["bento"]["stderr"].as_str().unwrap_or_default();
        if out != want_out || err != want_err {
            failed.push(format!(
                "{name}: mapping {:?} input {:?}\n  bento:  {want_out:?} {want_err:?}\n  ekiben: {out:?} {err:?}",
                field("mapping"),
                field("input")
            ));
        }
    }
    println!(
        "{} cases: {compared} compared, {} skipped, {} differ",
        cases.len(),
        cases.len() - compared,
        failed.len()
    );
    assert!(cases.len() >= 315, "only {} cases extracted", cases.len());
    assert!(failed.is_empty(), "{}", failed.join("\n"));
}
